import{buildSectionSelector,normalizeSectionId,sectionRenderer}from"@theme/section-renderer";import{requestIdleCallback,onDocumentReady}from"@theme/utilities";async function hydrateSection(e,t){const n=normalizeSectionId(e),o=document.getElementById(buildSectionSelector(n));o&&"true"!==o.dataset.hydrated&&(await sectionRenderer.renderSection(n,{cache:!1,url:t,mode:"hydration"}),o.dataset.hydrated="true")}export async function hydrate(e,t){onDocumentReady(()=>{requestIdleCallback(()=>hydrateSection(e,t))})}